SELECT
(SELECT count(*) FROM albums WHERE id='al-4a5d668099' AND name='星' AND year=2013 AND genre='Miscellaneous' AND cover_r2_key='covers/al-4a5d668099' AND song_count=14 AND duration=0 AND size=393027398 AND compilation=0) album_exact,
(SELECT count(*) FROM song_masters WHERE album_id='al-4a5d668099') album_masters,
(SELECT count(*) FROM song_instances si JOIN song_masters sm ON sm.id=si.master_id WHERE sm.album_id='al-4a5d668099' AND si.suffix='wav') wav_instances,
(SELECT count(*) FROM song_instances si JOIN song_masters sm ON sm.id=si.master_id WHERE sm.album_id='al-4a5d668099' AND si.suffix='flac') flac_instances,
(SELECT count(*) FROM song_instances si JOIN song_masters sm ON sm.id=si.master_id WHERE sm.album_id='al-4a5d668099' AND si.suffix='mp3') mp3_instances,
(SELECT count(*) FROM storage_objects WHERE id IN ('obj_4b5013bbc90dcb7d','obj_6c8c776a3c83d606','obj_99c8ade0ef6146c3','obj_ccabb13e4ac0ea00','obj_6a8b7641a9451c7c','obj_e3acbfdc775ee420','obj_ccfc3de8e869e030')) candidate_objects,
